def evaluate(text):
    """Value of an integer arithmetic expression. See TASK.md."""
    parser = _Parser(text)
    value = parser.parse()
    parser.expect_end()
    return value


class _Parser:
    """Recursive-descent parser.

    Precedence, lowest to highest (mirrors TASK.md rules 2-4):

        add   := mul (('+' | '-') mul)*            # left assoc
        mul   := unary (('*' | '//' | '%') unary)* # left assoc
        unary := ('+' | '-')* power                # signs bind tighter
        power := atom ('**' unary)?                # right assoc; right side
                                                    # is unary so '2 ** -1'
                                                    # parses (rule 4)
        atom  := number | '(' add ')'

    Because power sits above unary, '-2 ** 2' parses as -(2 ** 2) == -4
    (unary looser than **).  Because mul sits above unary, '2 * -3' parses
    as 2 * (-3) == -6 (unary tighter than *).
    """

    def __init__(self, text):
        self.text = text
        self.pos = 0

    # -- small helpers --------------------------------------------------------

    def peek(self):
        if self.pos < len(self.text):
            return self.text[self.pos]
        return None

    def at(self, ch):
        return self.peek() == ch

    def starts_with(self, s):
        return self.text.startswith(s, self.pos)

    def skip_ws(self):
        while self.peek() in (" ", "\t"):
            self.pos += 1

    # -- number (rule 1) ------------------------------------------------------

    def read_number(self):
        start = self.pos
        ch = self.peek()
        if ch == "0":
            self.pos += 1
            # a leading zero followed by another digit is invalid
            if self.peek() is not None and self.peek().isdigit():
                raise ValueError("leading zero in number")
            return 0
        if ch is not None and ch.isdigit():
            while self.peek() is not None and self.peek().isdigit():
                self.pos += 1
            return int(self.text[start:self.pos])
        raise ValueError("expected number")

    # -- grammar --------------------------------------------------------------

    def parse(self):
        return self.parse_add()

    def parse_add(self):
        left = self.parse_mul()
        while True:
            self.skip_ws()
            if self.at("+") or self.at("-"):
                op = self.text[self.pos]
                self.pos += 1
                right = self.parse_mul()
                left = left + right if op == "+" else left - right
            else:
                return left

    def parse_mul(self):
        left = self.parse_unary()
        while True:
            self.skip_ws()
            if self.starts_with("//"):
                self.pos += 2
                right = self.parse_unary()
                if right == 0:
                    raise ZeroDivisionError("integer division by zero")
                left = left // right
            elif self.at("%"):
                self.pos += 1
                right = self.parse_unary()
                if right == 0:
                    raise ZeroDivisionError("modulo by zero")
                left = left % right
            elif self.at("*") and not self.starts_with("**"):
                self.pos += 1
                right = self.parse_unary()
                left = left * right
            else:
                return left

    def parse_unary(self):
        self.skip_ws()
        negate = False
        while self.at("+") or self.at("-"):
            op = self.text[self.pos]
            self.pos += 1
            if op == "-":
                negate = not negate
            self.skip_ws()
        value = self.parse_power()
        return -value if negate else value

    def parse_power(self):
        left = self.parse_atom()
        self.skip_ws()
        if self.starts_with("**"):
            self.pos += 2
            # the exponent may carry unary signs (rule 4: '2 ** -1' parses)
            right = self.parse_unary()
            if right < 0:
                raise ValueError("negative exponent")  # rule 6
            return left ** right
        return left

    def parse_atom(self):
        self.skip_ws()
        ch = self.peek()
        if ch == "(":
            self.pos += 1
            value = self.parse()
            self.skip_ws()
            if not self.at(")"):
                raise ValueError("expected ')'")
            self.pos += 1
            return value
        if ch is not None and ch.isdigit():
            return self.read_number()
        raise ValueError("expected atom")

    # -- end ------------------------------------------------------------------

    def expect_end(self):
        self.skip_ws()
        if self.pos != len(self.text):
            raise ValueError("unexpected trailing input")
